(function () {
  const $ = (sel, root) => (root || document).querySelector(sel)
  const $$ = (sel, root) => Array.from((root || document).querySelectorAll(sel))

  const state = {
    activeId: null,
    requestId: null,
    streaming: false,
    streamingReasoningActive: false,
    webMode: false,
    trashMode: false,
    chatSearch: '',
    collapsedFolders: new Set()
  }

  const LOGO = '<img src="data:image/png;base64," style="display:block;width:100%;height:100%;object-fit:contain">'

  const SUGGESTIONS = ['suggestion_code', 'suggestion_plan', 'suggestion_idea', 'suggestion_summary']

  function esc(s) {
    return String(s == null ? '' : s)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;')
  }

  // ---------- 基础工具 ----------
  function hexToRgba(hex, alpha) {
    const m = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex)
    if (!m) return `rgba(77,107,254,${alpha})`
    const [r, g, b] = [parseInt(m[1], 16), parseInt(m[2], 16), parseInt(m[3], 16)]
    return `rgba(${r},${g},${b},${alpha})`
  }

  let toastTimer = null
  function toast(text) {
    let el = $('#toast')
    if (!el) {
      el = document.createElement('div')
      el.id = 'toast'
      el.style.cssText =
        'position:fixed;left:50%;bottom:28px;transform:translateX(-50%);background:var(--text);color:var(--bg);padding:9px 16px;border-radius:10px;font-size:13px;z-index:300;box-shadow:var(--shadow);opacity:0;transition:opacity .2s'
      document.body.appendChild(el)
    }
    el.textContent = text
    requestAnimationFrame(() => (el.style.opacity = '1'))
    clearTimeout(toastTimer)
    toastTimer = setTimeout(() => (el.style.opacity = '0'), 1800)
  }

  function relativeTime(ts) {
    if (!ts) return ''
    const diff = Date.now() - ts
    const min = 60 * 1000
    const hour = 60 * min
    const day = 24 * hour
    const t = window.I18N ? window.I18N.t : (k) => k
    if (diff < min) return t('rel_just_now')
    if (diff < hour) return Math.floor(diff / min) + ' ' + t('rel_minutes_ago')
    if (diff < day) return Math.floor(diff / hour) + ' ' + t('rel_hours_ago')
    const d = new Date(ts)
    const now = new Date()
    const fmt = (n) => String(n).padStart(2, '0')
    if (d.toDateString() === now.toDateString()) return t('rel_today') + ' ' + fmt(d.getHours()) + ':' + fmt(d.getMinutes())
    const yest = new Date(now.getTime() - day)
    if (d.toDateString() === yest.toDateString()) return t('rel_yesterday') + ' ' + fmt(d.getHours()) + ':' + fmt(d.getMinutes())
    return fmt(d.getMonth() + 1) + '-' + fmt(d.getDate())
  }

  // ---------- 主题 / 外观应用 ----------
  function applyTheme(settings) {
    const mode = settings.theme
    let theme = mode
    if (mode === 'system') {
      theme = window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light'
    }
    document.documentElement.setAttribute('data-theme', theme)

    const root = document.documentElement
    root.style.setProperty('--accent', settings.accent)
    root.style.setProperty('--accent-soft', hexToRgba(settings.accent, 0.12))

    const codeTheme = settings.codeTheme === 'auto' ? theme : settings.codeTheme
    root.setAttribute('data-code-theme', codeTheme)

    const fonts = { small: 13, medium: 15, large: 17, xlarge: 19 }
    root.style.setProperty('--font-message', (fonts[settings.fontSize] || 15) + 'px')
    const lh = { compact: 1.55, normal: 1.75, relaxed: 1.95 }
    root.style.setProperty('--line-height', lh[settings.lineHeight] || 1.75)
    const mw = { narrow: 620, standard: 768, wide: 980 }
    root.style.setProperty('--msg-max-width', (mw[settings.messageWidth] || 768) + 'px')
    root.style.setProperty('--sidebar-width', (settings.sidebarWidth || 264) + 'px')
    root.style.setProperty('--input-rows', settings.inputRows || 3)
    root.style.setProperty('--bg-dim-dark', settings.background.dimDark ? 1 : 0)
    root.style.setProperty('--bg-image-opacity', (settings.background.opacity || 40) / 100)

    $$('.msg-user').forEach((n) => n.classList.remove('filled', 'outlined'))
    $$('.msg-user').forEach((n) => n.classList.add(settings.bubbleStyle === 'outlined' ? 'outlined' : 'filled'))

    if (window.mermaid && window.__mmdTheme !== theme) {
      window.__mmdTheme = theme
      window.mermaid.initialize({ startOnLoad: false, securityLevel: 'strict', theme: theme === 'dark' ? 'dark' : 'default' })
    }
  }

  function applyBackground(settings) {
    const bg = settings.background || { type: 'none' }
    const main = $('#main')
    const root = document.documentElement
    if (bg.type === 'image' && bg.value) {
      main.style.background = ''
      root.style.setProperty('--bg-image', `url("${bg.value}")`)
      root.style.setProperty('--bg-size', bg.fit === 'contain' ? 'contain' : bg.fit === 'tile' ? 'auto' : 'cover')
      root.style.setProperty('--bg-repeat', bg.fit === 'tile' ? 'repeat' : 'no-repeat')
    } else if (bg.type === 'color' && bg.value) {
      root.style.setProperty('--bg-image', 'none')
      main.style.background = bg.value
    } else if (bg.type === 'gradient' && bg.value) {
      root.style.setProperty('--bg-image', 'none')
      main.style.background = bg.value
    } else {
      root.style.setProperty('--bg-image', 'none')
      main.style.background = ''
    }
  }

  function applyAll(settings) {
    applyTheme(settings)
    applyBackground(settings)
  }

  // ---------- 渲染：欢迎页 ----------
  function renderWelcome() {
    const area = $('#messages')
    area.innerHTML = ''
    const t = window.I18N.t
    const w = document.createElement('div')
    w.className = 'welcome'
    w.innerHTML = `
      <div class="welcome-logo">${LOGO}</div>
      <h1>${t('welcome_title')}</h1>
      <div class="welcome-sub">${t('welcome_sub')}</div>
      <div class="welcome-cards">
        ${SUGGESTIONS.map((s, i) => `<button class="welcome-card" data-s="s${i}">
          <svg viewBox="0 0 24 24" class="icon sm"><path d="M12 2a4 4 0 0 1 4 4v6a4 4 0 0 1-8 0V6a4 4 0 0 1 4-4zm7 8a1 1 0 0 1 1 1 8 8 0 0 1-16 0 1 1 0 0 1 2 0 6 6 0 0 0 12 0 1 1 0 0 1 1-1zM12 20a5 5 0 0 0 5-5h2a7 7 0 0 1-14 0h2a5 5 0 0 0 5 5z" fill="currentColor"/></svg>
          ${t(SUGGESTIONS[i])}</button>`).join('')}
      </div>`
    area.appendChild(w)
  }

  // ---------- 渲染：消息 ----------
  function renderMessage(msg, streaming) {
    const t = window.I18N.t
    if (!msg._id) msg._id = 'm_' + Math.random().toString(36).slice(2, 14)
    const node = document.createElement('div')
    if (msg.role === 'user') {
      node.className = 'msg msg-user ' + (window.Store.getSettings().bubbleStyle === 'outlined' ? 'outlined' : 'filled')
      const content = document.createElement('div')
      content.className = 'msg-content'
      content.innerHTML = window.MD.renderPlain(msg.content || '')
      node.appendChild(content)
      const actions = document.createElement('div')
      actions.className = 'msg-actions'
      actions.innerHTML = `
        <button class="act-btn" data-act="regenerate" data-id="${msg._id}" title="${t('msg_regenerate')}"><svg class="icon" viewBox="0 0 24 24"><path d="M17.65 6.35A8 8 0 1 0 19.73 14H17a6 6 0 1 1-1.07-6.34L14 10h7V3l-3.35 3.35z" fill="currentColor"/></svg></button>
        <button class="act-btn" data-act="editmsg" data-id="${msg._id}" title="${t('msg_edit')}"><svg class="icon" viewBox="0 0 24 24"><path d="M3 17.25V21h3.75L17.81 9.94l-3.75-3.75L3 17.25zM20.71 7.04a1 1 0 0 0 0-1.41l-2.34-2.34a1 1 0 0 0-1.41 0l-1.83 1.83 3.75 3.75 1.83-1.83z" fill="currentColor"/></svg></button>`
      node.appendChild(actions)
      return node
    }

    node.className = 'msg msg-assistant'

    const labels = window.MODEL_LABELS || {}
    const modelName = msg.model ? (labels[msg.model] || msg.model) : 'DeepSeek'
    const label = document.createElement('div')
    label.className = 'msg-label'
    label.innerHTML = `<span class="icon">${LOGO}</span><span>${esc(modelName)}</span>`
    node.appendChild(label)

    const variantCount = Array.isArray(msg.variants) ? msg.variants.length : 0
    if (variantCount > 1) {
      const nav = document.createElement('div')
      nav.className = 'variant-nav'
      const idx = typeof msg.vindex === 'number' ? msg.vindex : variantCount - 1
      nav.innerHTML =
        `<button class="act-btn ver-btn" data-act="prevver" data-id="${msg._id}" title="${t('prev_version')}">‹</button>` +
        `<span class="ver-pos">${idx + 1}/${variantCount}</span>` +
        `<button class="act-btn ver-btn" data-act="nextver" data-id="${msg._id}" title="${t('next_version')}">›</button>`
      node.appendChild(nav)
    }

    if (msg.searched) {
      const tag = document.createElement('span')
      tag.className = 'search-badge'
      tag.textContent = '🔍 ' + t('searched')
      node.appendChild(tag)
    }

    const hasReasoning = msg.reasoning || (streaming && state.streamingReasoningActive)
    if (hasReasoning) {
      const details = document.createElement('details')
      details.className = 'reasoning'
      if (streaming) details.classList.add('streaming')
      else details.open = false
      const summary = document.createElement('summary')
      summary.textContent = t('reasoning_summary')
      const body = document.createElement('div')
      body.className = 'reasoning-body'
      body.textContent = msg.reasoning || ''
      details.appendChild(summary)
      details.appendChild(body)
      node.appendChild(details)
    }

    const content = document.createElement('div')
    content.className = 'msg-content'
    if (streaming) {
      content.classList.add('cursor')
      content.textContent = msg.content || ''
    } else {
      if (window.Store.getSettings().markdown) {
        content.innerHTML = window.MD.renderMarkdown(msg.content || '')
      } else {
        content.innerHTML = window.MD.renderPlain(msg.content || '')
      }
    }
    node.appendChild(content)

    if (msg.error) {
      const err = document.createElement('div')
      err.className = 'msg-error'
      err.textContent = msg.error
      node.appendChild(err)
    }

    if (!streaming) {
      const actions = document.createElement('div')
      actions.className = 'msg-actions'
      actions.innerHTML = `
        <button class="act-btn" data-act="copy" data-id="${msg._id}" title="${t('msg_copy')}"><svg class="icon" viewBox="0 0 24 24"><path d="M16 1H4a2 2 0 0 0-2 2v14h2V3h12V1zm3 4H8a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h11a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2zm0 16H8V7h11v14z" fill="currentColor"/></svg></button>
        <button class="act-btn" data-act="speak" data-id="${msg._id}" title="${t('msg_speak')}"><svg class="icon" viewBox="0 0 24 24"><path d="M11 5L6 9H2v6h4l5 4V5zM15.5 8.5a5 5 0 0 1 0 7M18.5 5.5a9 9 0 0 1 0 13" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg></button>
        <button class="act-btn" data-act="regenerate" data-id="${msg._id}" title="${t('msg_regenerate')}"><svg class="icon" viewBox="0 0 24 24"><path d="M17.65 6.35A8 8 0 1 0 19.73 14H17a6 6 0 1 1-1.07-6.34L14 10h7V3l-3.35 3.35z" fill="currentColor"/></svg></button>
        <button class="act-btn" data-act="delmsg" data-id="${msg._id}" title="${t('msg_delete')}"><svg class="icon" viewBox="0 0 24 24"><path d="M6 19a2 2 0 0 0 2 2h8a2 2 0 0 0 2-2V7H6v12zM19 4h-3.5l-1-1h-5l-1 1H5v2h14V4z" fill="currentColor"/></svg></button>`
      node.appendChild(actions)
    }

    if (msg.usage) {
      const usage = document.createElement('div')
      usage.className = 'msg-usage'
      usage.textContent = `${t('prompt_tokens')}: ${msg.usage.prompt || 0} · ${t('completion_tokens')}: ${msg.usage.completion || 0} · ${t('total_tokens')}: ${msg.usage.total || 0}`
      node.appendChild(usage)
    }

    return node
  }

  function renderMessages() {
    const conv = window.Store.getConversation(state.activeId)
    const area = $('#messages')
    area.innerHTML = ''
    if (!conv || !conv.messages.length) {
      renderWelcome()
      return
    }
    conv.messages.forEach((msg, i) => {
      const streaming = state.streaming && i === conv.messages.length - 1 && msg.role === 'assistant'
      area.appendChild(renderMessage(msg, streaming))
    })
    scrollToBottom(true)
    window.MD.renderDiagrams(area)
  }

  function scrollToBottom(force) {
    const area = $('#messages')
    const nearBottom = area.scrollHeight - area.scrollTop - area.clientHeight < 120
    if (force || nearBottom) {
      area.scrollTop = area.scrollHeight
    }
  }

  // ---------- 渲染：侧栏 ----------
  function renderChatList() {
    const list = $('#chat-list')
    list.innerHTML = ''
    const t = window.I18N.t

    if (state.trashMode) {
      const head = document.createElement('div')
      head.className = 'trash-head'
      head.innerHTML = `<span>${t('trash_btn')}</span><button class="trash-empty">${t('trash_empty_btn')}</button>`
      list.appendChild(head)
      const items = window.Store.getTrash()
      if (!items.length) {
        const hint = document.createElement('div')
        hint.className = 'trash-empty-hint'
        hint.textContent = t('trash_empty')
        list.appendChild(hint)
        return
      }
      items.forEach((c) => {
        const item = document.createElement('div')
        item.className = 'chat-item trash'
        item.dataset.id = c.id
        item.innerHTML = `
        <div class="chat-title"></div>
        <div class="chat-ops">
          <button class="op-restore" title="${t('restore')}">
            <svg viewBox="0 0 24 24" class="icon"><path d="M3 12a9 9 0 1 0 3-6.7L3 8M3 3v5h5" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>
          </button>
          <button class="op-delete" title="${t('purge')}">
            <svg viewBox="0 0 24 24" class="icon"><path d="M3 6h18M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2m3 0v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6h14z" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>
          </button>
        </div>`
        item.querySelector('.chat-title').textContent = c.title
        item.title = c.title
        list.appendChild(item)
      })
      return
    }

    const kw = (state.chatSearch || '').trim().toLowerCase()
    const matched = window.Store.getConversations().filter((c) => {
      if (!kw) return true
      if ((c.title || '').toLowerCase().includes(kw)) return true
      return (c.messages || []).some((m) => (m.content || '').toLowerCase().includes(kw))
    })
    const convs = matched.slice().sort((a, b) => {
      if (!!b.pinned !== !!a.pinned) return b.pinned ? 1 : -1
      return (b.updatedAt || 0) - (a.updatedAt || 0)
    })

    function createChatItem(c) {
      const item = document.createElement('div')
      item.className = 'chat-item' + (c.id === state.activeId ? ' active' : '') + (c.pinned ? ' pinned' : '')
      item.dataset.id = c.id
      item.innerHTML = `
        <div class="chat-title"></div>
        <div class="chat-ops">
          <button class="op-pin" title="${c.pinned ? t('unpin') : t('pin')}">
            <svg viewBox="0 0 24 24" class="icon"><path d="M16 3l5 5-5.5 1.5L12 13l-1.5 4.5L6 22l-2-2 4.5-4.5L10 11l3.5-3.5z" stroke="currentColor" stroke-width="2" fill="${c.pinned ? 'currentColor' : 'none'}" stroke-linejoin="round"/></svg>
          </button>
          <button class="op-folder" title="${t('move_to_folder')}">
            <svg viewBox="0 0 24 24" class="icon"><path d="M3 7a2 2 0 0 1 2-2h4l2 2h8a2 2 0 0 1 2 2v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V7z" stroke="currentColor" stroke-width="2" fill="none" stroke-linejoin="round"/></svg>
          </button>
          <button class="op-export" title="${t('conv_export')}">
            <svg viewBox="0 0 24 24" class="icon"><path d="M12 3v12m0 0l-4-4m4 4l4-4M4 17v2a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2v-2" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>
          </button>
          <button class="op-rename" title="${t('rename')}">
            <svg viewBox="0 0 24 24" class="icon"><path d="M11 4H4a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2v-7M18.5 2.5a2.12 2.12 0 0 1 3 3L12 15l-4 1 1-4 9.5-9.5z" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>
          </button>
          <button class="op-delete" title="${t('delete')}">
            <svg viewBox="0 0 24 24" class="icon"><path d="M3 6h18M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2m3 0v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6h14z" stroke="currentColor" stroke-width="2" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>
          </button>
        </div>`
      item.querySelector('.chat-title').textContent = c.title
      item.title = c.title
      return item
    }

    function createFolderHead(name, count) {
      const collapsed = state.collapsedFolders.has(name)
      const head = document.createElement('div')
      head.className = 'folder-head' + (collapsed ? ' collapsed' : '')
      head.dataset.folder = name
      head.innerHTML = `
        <span class="folder-arrow">${collapsed ? '▸' : '▾'}</span>
        <span class="folder-name"></span>
        <span class="folder-count">${count}</span>
        <button class="folder-del" title="${t('remove_folder')}">&times;</button>`
      head.querySelector('.folder-name').textContent = name
      return head
    }

    const pinnedItems = convs.filter((c) => c.pinned)
    const rest = convs.filter((c) => !c.pinned)
    const folderMap = new Map()
    const ungrouped = []
    rest.forEach((c) => {
      if (c.folder) {
        if (!folderMap.has(c.folder)) folderMap.set(c.folder, [])
        folderMap.get(c.folder).push(c)
      } else {
        ungrouped.push(c)
      }
    })

    if (!convs.length) {
      const empty = document.createElement('div')
      empty.className = 'chat-list-empty'
      empty.textContent = kw ? t('search_no_result') : ''
      list.appendChild(empty)
      return
    }

    if (pinnedItems.length && !kw) {
      const label = document.createElement('div')
      label.className = 'list-section-label'
      label.textContent = t('pinned_section')
      list.appendChild(label)
      pinnedItems.forEach((c) => list.appendChild(createChatItem(c)))
    }

    Array.from(folderMap.keys()).sort((a, b) => a.localeCompare(b)).forEach((name) => {
      const items = folderMap.get(name)
      list.appendChild(createFolderHead(name, items.length))
      if (!state.collapsedFolders.has(name)) items.forEach((c) => list.appendChild(createChatItem(c)))
    })

    ungrouped.forEach((c) => list.appendChild(createChatItem(c)))
  }

  // ---------- 设置面板 ----------
  function bindSegmented(containerId, value) {
    const seg = document.getElementById(containerId)
    if (!seg) return
    $$('button', seg).forEach((b) => b.classList.toggle('active', b.dataset.val === value))
  }

  function syncSettingsPanel(settings) {
    bindSegmented('theme-mode-seg', settings.theme)
    bindSegmented('code-theme-seg', settings.codeTheme)
    bindSegmented('bubble-style-seg', settings.bubbleStyle)
    bindSegmented('bg-type-seg', settings.background.type)

    $$('#accent-swatches .swatch').forEach((s) => s.classList.toggle('active', s.dataset.color === settings.accent))
    $('#accent-custom').value = settings.accent
    $$('#bg-color-section .swatch').forEach((s) => s.classList.toggle('active', s.dataset.bgcolor === settings.background.value))
    $('#bg-color-custom').value = /^#/.test(settings.background.value || '') ? settings.background.value : '#eef2ff'
    $$('.gradient-opt').forEach((g) => g.classList.toggle('active', g.dataset.gradient === settings.background.value))

    $('#set-font-size').value = settings.fontSize
    $('#set-line-height').value = settings.lineHeight
    $('#set-message-width').value = settings.messageWidth
    $('#set-input-rows').value = String(settings.inputRows)
    $('#set-typing-anim').checked = settings.typingAnim
    $('#set-markdown').checked = settings.markdown
    $('#set-auto-title').checked = settings.autoTitle
    $('#set-notify-on-reply').checked = settings.notifyOnReply
    $('#set-shortcut-enabled').checked = settings.shortcutEnabled
    $('#set-shortcut-accel').value = settings.shortcutAccelerator || 'CommandOrControl+Alt+D'
    $('#set-auto-backup').checked = settings.autoBackup !== false
    $('#set-language').value = settings.language
    $('#set-bg-fit').value = settings.background.fit
    $('#set-bg-opacity').value = settings.background.opacity
    $('#bg-opacity-val').textContent = settings.background.opacity + '%'
    $('#set-bg-dim').checked = settings.background.dimDark

    syncApiProfiles(settings)
    const creds = window.Store.activeApiCreds()
    $('#set-api-key').value = creds.apiKey || ''
    $('#set-base-url').value = creds.baseUrl || 'https://api.deepseek.com'

    $('#bg-color-section').hidden = settings.background.type !== 'color'
    $('#bg-gradient-section').hidden = settings.background.type !== 'gradient'
    $('#bg-image-section').hidden = settings.background.type !== 'image'
    renderBgImageList(settings)
  }

  function syncApiProfiles(settings) {
    const select = $('#api-profile')
    if (!select) return
    const profiles = (settings.apiProfiles || []).slice()
    const activeId = settings.activeProfileId || ''
    let html = profiles
      .map(
        (p) =>
          `<option value="${esc(p.id)}"${p.id === activeId ? ' selected' : ''}>${esc((p.name || '档案').slice(0, 24))}${p.id === activeId ? ' ●' : ''}</option>`
      )
      .join('')
    if (!profiles.length) {
      html += `<option value="__empty__" disabled selected>— 无档案 —</option>`
    }
    html += `<option value="__new__">＋ 新建档案</option>`
    select.innerHTML = html
    const nameWrap = $('#api-profile-name-wrap')
    const showName = activeId && activeId !== 'default'
    nameWrap.hidden = !showName
    if (showName) {
      const active = profiles.find((p) => p.id === activeId)
      $('#api-profile-name').value = active ? active.name || '' : ''
    }
  }

  function renderBgImageList(settings) {
    const list = $('#bg-image-list')
    list.innerHTML = ''
    const images = (settings.background.images || []).map((p) => p.path)
    images.forEach((path) => {
      const thumb = document.createElement('div')
      thumb.className = 'bg-image-thumb' + (path === settings.background.value ? ' active' : '')
      thumb.style.backgroundImage = `url("${path}")`
      thumb.dataset.path = path
      thumb.innerHTML = `<button class="del">&times;</button>`
      list.appendChild(thumb)
    })
  }

  function renderModelPanel(models) {
    const panel = $('#model-panel')
    if (!panel || !Array.isArray(models) || !models.length) return
    const conv = window.Store.getConversation(state.activeId) || {}
    const active = conv.model
    const labels = window.MODEL_LABELS || {}
    panel.innerHTML = ''
    const count = document.createElement('div')
    count.className = 'model-count'
    count.textContent = window.I18N.t('models_count').replace('{n}', String(models.length))
    panel.appendChild(count)
    models.forEach((m) => {
      const btn = document.createElement('button')
      btn.className = 'model-opt' + (m === active ? ' active' : '')
      btn.dataset.model = m
      const name = labels[m] || m
      btn.innerHTML = `<div><div class="model-name">${esc(name)}</div><div class="model-desc">${esc(m)}</div></div>`
      panel.appendChild(btn)
    })
  }

  // ---------- 弹层定位 ----------
  function openPopover(pop, anchor) {
    const rect = anchor.getBoundingClientRect()
    pop.hidden = false
    pop.style.top = rect.bottom + 8 + 'px'
    pop.style.left = Math.min(rect.left, window.innerWidth - pop.offsetWidth - 12) + 'px'
  }

  function closePopovers() {
    $$('.popover').forEach((p) => (p.hidden = true))
  }

  // ---------- 输入框 ----------
  function resizeInput() {
    const ta = $('#chat-input')
    ta.style.height = 'auto'
    const max = (window.Store.getSettings().inputRows || 3) * 26
    ta.style.height = Math.min(ta.scrollHeight, Math.max(26, max)) + 'px'
  }

  // ---------- 模式切换 ----------
  function setWebMode(on) {
    state.webMode = on
    $('#sidebar').hidden = on
    $('#main').hidden = on
    $('#webview-view').hidden = !on
    $('#mode-toggle-label').textContent = on ? window.I18N.t('mode_api') : window.I18N.t('mode_web')
    if (on) {
      const webview = $('#deepseek-webview')
      if (!webview.getAttribute('src')) {
        webview.setAttribute('src', 'https://chat.deepseek.com')
        $('#webview-loading').style.display = 'flex'
      }
    }
  }

  // ---------- 对外接口 ----------
  const UI = {
    state,
    LOGO,
    applyAll,
    applyTheme,
    applyBackground,
    renderWelcome,
    renderMessages,
    renderChatList,
    renderMessage,
    scrollToBottom,
    syncSettingsPanel,
    renderBgImageList,
    renderModelPanel,
    openPopover,
    closePopovers,
    resizeInput,
    setWebMode,
    toast,
    esc
  }

  window.UI = UI
})()